import java.util.*;

class Solution {
  public int longestEqualSubarray(List<Integer> nums, int k) {
    Map<Integer, Integer> counts = new HashMap<>();
    int left = 0, bestFrequency = 0, answer = 0;
    for (int right = 0; right < nums.size(); right++) {
      int value = nums.get(right);
      int frequency = counts.merge(value, 1, Integer::sum);
      bestFrequency = Math.max(bestFrequency, frequency);
      while (right - left + 1 - bestFrequency > k) {
        counts.merge(nums.get(left++), -1, Integer::sum);
      }
      answer = Math.max(answer, bestFrequency);
    }
    return answer;
  }
}
